head.script:
scwin.select1_onviewchange = function(info) {
    _onchange = true;
    //alert('onviewChange!!');
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. IE 브라우저에서 샘플파일을 실행 후 체크박스 옆의 라벨("2")을 클릭한다.
    //1. Run the sample file in the IE browser and click the label ("2") next to the check box.
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2checkbox_label ')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. onviewChange가 정상적으로 동작한다. (이전에는 라벨클릭시 동작하지 않음. 체크박스는 이전에도 정상적으로 동작했음)
    //1. onviewChange works normally. (Previously, it did not work when the label was clicked.
    WebSquare.wUnit.addCommand("assert", "_onchange", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window._onchange = false;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
